    const GURL& requesting_origin,
    const GURL& embedding_origin) {
  std::vector<std::unique_ptr<ChooserContextBase::Object>> results;

  if (!requesting_origin.is_valid() || !embedding_origin.is_valid()) {
    return results;
  }

  WebsiteSettings* website_settings = GetWebsiteSettings();
  if (!website_settings || !CanGrantPermission(requesting_origin, embedding_origin)) {
    return results;
  }

  const auto* object_list = website_settings->GetObjectList(requesting_origin, embedding_origin);
  if (!object_list || object_list->empty()) {
    return results;
  }

